def count_knight_degrees(rows, cols):
    degrees = []
    for r in range(rows):
        for c in range(cols):
            degree = 0
            for dr, dc in [(2,1), (2,-1), (-2,1), (-2,-1), (1,2), (1,-2), (-1,2), (-1,-2)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    degree += 1
            degrees.append(degree)
    return sorted(degrees)

