def solve_queen_coverage(m, n):
    # m x n board. Assume (r, c) is a white square if (r+c) % 2 == 0.
    # A queen is placed on some square (r, c). 
    # We want to find a square (r, c) that attacks the maximum number of white squares.
    max_white_attacked = 0
    for r in range(m):
        for c in range(n):
            # Check if (r, c) is a white square
            if (r + c) % 2 == 0:
                attacked = 0
                # Row r
                for j in range(n):
                    if j != c and (r + j) % 2 == 0:
                        attacked += 1
                # Col c
                for i in range(m):
                    if i != r and (i + c) % 2 == 0:
                        attacked += 1
                # Diag \ (r-c = const)
                for i in range(m):
                    j = i - (r - c)
                    if 0 <= j < n and i != r and j != c and (i + j) % 2 == 0:
                        attacked += 1
                # Diag / (r+c = const)
                for i in range(m):
                    j = (r + c) - i
                    if 0 <= j < n and i != r and j != c and (i + j) % 2 == 0:
                        attacked += 1
                max_white_attacked = max(max_white_attacked, attacked)
    return max_white_attacked

