def count_black_squares_attacked_by_queen(r, c, rows, cols):
    # Assume (r, c) is 0-indexed
    # A square (i, j) is black if (i + j) % 2 == 1 (or 0, let's pick one)
    # Let's use (i + j) % 2 == 1 as black.
    black_squares = set()
    # Row
    for j in range(cols):
        if (r + j) % 2 == 1:
            black_squares.add((r, j))
    # Column
    for i in range(rows):
        if (i + c) % 2 == 1:
            black_squares.add((i, c))
    # Diagonals
    # Diagonal 1: i - j = r - c
    for i in range(rows):
        j = i - (r - c)
        if 0 <= j < cols:
            if (i + j) % 2 == 1:
                black_squares.add((i, j))
    # Diagonal 2: i + j = r + c
    for i in range(rows):
        j = (r + c) - i
        if 0 <= j < cols:
            if (i + j) % 2 == 1:
                black_squares.add((i, j))
    return len(black_squares)

